  - { kind: agent, ref: agents/dev-graph-parallel-safety-verifier, tier: core }
  - { kind: agent, ref: agents/dev-graph-requirements-verifier, tier: core }
  - { kind: agent, ref: agents/dev-graph-sync-conflict-verifier, tier: core }
  - { kind: command, ref: commands/dev-graph, tier: core }
  - { kind: hook, ref: "hook:PreToolUse-BashWriteEditMultiEditNotebookEdit/guard-graph-schema", tier: core }
  - { kind: hook, ref: "hook:SessionStart-startupresume/reconcile-task-lifecycle", tier: core }
  - { kind: hook, ref: "hook:PostToolUse-Bash/reconcile-task-lifecycle", tier: core }
  - { kind: hook, ref: "hook:PostToolUse-Bash/audit-graph-authority-drift", tier: core }
  - { kind: hook, ref: "hook:TaskCompleted/reconcile-task-lifecycle", tier: core }

  - {kind: script, ref: scripts/resolve-repo-context.py, tier: core}
  - {kind: script, ref: scripts/validate-graph-schema.py, tier: core}
  - {kind: script, ref: scripts/gh-bridge.py, tier: core}
  - {kind: script, ref: scripts/bd-bridge.py, tier: core}
  - {kind: script, ref: scripts/manage-worktree-lease.py, tier: core}
  - {kind: script, ref: scripts/reconcile-github-lifecycle.py, tier: core}
  - {kind: script, ref: scripts/render-graph-html.py, tier: core}
  - {kind: script, ref: scripts/schedule-graph.py, tier: core}
  - {kind: script, ref: scripts/register-package.py, tier: core}
  - {kind: script, ref: scripts/build-graph-node.py, tier: core}
  - {kind: script, ref: scripts/build-parity-manifest.py, tier: core}
  - {kind: script, ref: scripts/build-merged-graph.py, tier: core}
  - {kind: script, ref: scripts/lint-open-residue.py, tier: core}
  - {kind: script, ref: scripts/lint-orphan-external-ref.py, tier: core}

internal_support:
  - ref: scripts/_common.py
    owners: [C11, C12, C13, C16, C24, C26, C27, C28, C29]
    purpose: top-level capability ではなく、plugin-root scripts が共有する内部 runtime helper
  - ref: lib/graph_artifact_readiness.py
    owners: [C11]
    purpose: validate-graph-schema が artifact 本文の必須見出しと placeholder を判定する純関数
  - ref: lib/schedule_graph_nodes.py
    owners: [C16]
    purpose: schedule-graph が共有する node 述語 (resource_scope・schedulable・推移依存・P01 入口ゲート)
  - ref: lib/graph_envelope.py
    owners: [C02, C10, C11]
    purpose: graph.json envelope の形検査。validator・guard・事後検出・merge driver が同じ判定を使う
  - ref: lib/guard_graph_commands.py
    owners: [C10]
    purpose: guard が Bash コマンドから graph authority への書込みを判定する解析
  - ref: lib/guard_python_writes.py
    owners: [C10]
    purpose: guard がその場で実行される Python の書込み先を判定する解析
  - ref: lib/guard_python_path_eval.py
    owners: [C10]
    purpose: guard_python_writes が書込み先 path 式を静的に評価する補助
  - ref: lib/bd_bridge_contracts.py
    owners: [C16, C28]
    purpose: bd-bridge の受理語彙と純粋判定。MVP_FIT_RANK は schedule-graph も候補の選定順に使う
  - ref: lib/bd_bridge_graph.py
    owners: [C28]
    purpose: bd-bridge が graph 側の正本 (graph・parity manifest・spec) を read-only で解決する
  - ref: lib/bd_bridge_audit.py
    owners: [C28]
    purpose: bd-bridge の書かない監査 (orphan 棚卸し・node 削除 preflight)
  - ref: lib/orphan_external_ref.py
    owners: [C28]
    purpose: lint-orphan-external-ref が Beads の external_ref と graph node の対応を突合する判定
  - ref: lib/live_trial_evidence_selection.py
    owners: []
    purpose: criteria receipt が採用した PASS live-trial 証跡を選ぶ read-only helper。repository root の live-trial verdict lint が import する

